	protected RateCard read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created RateCard" );

		RateCard entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read RateCard with primary key" );
		msg.append( rateCardId );
		
		RateCardFetchOneSummary fetchOneSummary = new RateCardFetchOneSummary( rateCardId );

		try {
			entity = RateCardService.getRateCardInstance().getRateCard( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found RateCard " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a RateCard.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a RateCard." );

		StringBuilder msg = new StringBuilder( "Failed to update a RateCard : " );        
		RateCard entity = read();
		UpdateRateCardCommand command = generateUpdateCommand();
		command.setRateCardId(entity.getRateCardId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created RateCard." );

			// for use later on...
			rateCardId = entity.getRateCardId();

			RateCardService proxy = RateCardService.getRateCardInstance();  

			proxy.updateRateCard( command ).get();

			LOGGER.info( "-- Successfully saved RateCard - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + rateCardId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a RateCard.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created RateCard." );

		RateCard entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read RateCard with id " + rateCardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read RateCard with id " + rateCardId );

			throw e;
		}

		try{
			RateCardService.getRateCardInstance().delete( new DeleteRateCardCommand( entity.getRateCardId() ) ).get();
			LOGGER.info( "-- Successfully deleted RateCard with id " + rateCardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete RateCard with id " + rateCardId );

			throw e;
		}
	}

	/**
	 * get all RateCards.
	 */
	protected List<RateCard> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of RateCards:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all RateCard : " );        
		List<RateCard> collection  = new ArrayList<>();

		try {
			// call the static get method on the RateCardService
			collection = RateCardService.getRateCardInstance().getAllRateCard();
			assertNotNull( collection, "An Empty collection of RateCard was incorrectly returned.");
			
			// Now print out the values
			RateCard entity = null;            
			Iterator<RateCard> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRateCardId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

